mkitem!{mkimpl!{impl < 'tcx > TypeFoldable < TyCtxt < 'tcx > > for GenericArgsRef < 'tcx > { fn try_fold_with < F : FallibleTypeFolder < TyCtxt < 'tcx > > > (self , folder : & mut F ,) -> Result < Self , F :: Error > { match self . len () { 1 => { let param0 = self [0] . try_fold_with (folder) ? ; if param0 == self [0] { Ok (self) } else { Ok (folder . cx () . mk_args (& [param0])) } } 2 => { let param0 = self [0] . try_fold_with (folder) ? ; let param1 = self [1] . try_fold_with (folder) ? ; if param0 == self [0] && param1 == self [1] { Ok (self) } else { Ok (folder . cx () . mk_args (& [param0 , param1])) } } 0 => Ok (self) , _ => ty :: util :: try_fold_list (self , folder , | tcx , v | tcx . mk_args (v)) , } } fn fold_with < F : TypeFolder < TyCtxt < 'tcx > > > (self , folder : & mut F) -> Self { match self . len () { 1 => { let param0 = self [0] . fold_with (folder) ; if param0 == self [0] { self } else { folder . cx () . mk_args (& [param0]) } } 2 => { let param0 = self [0] . fold_with (folder) ; let param1 = self [1] . fold_with (folder) ; if param0 == self [0] && param1 == self [1] { self } else { folder . cx () . mk_args (& [param0 , param1]) } } 0 => self , _ => ty :: util :: fold_list (self , folder , | tcx , v | tcx . mk_args (v)) , } } }}}
